#[allow(dead_code)]
fn stateful_contract(mut el: Stateful<Div>) -> Stateful<Div> {
    el = el.aria_active_descendant();
    el = el.focusable();
    el = el.overflow_scroll();
    el = el.overflow_x_scroll();
    el = el.overflow_y_scroll();
    el = el.restrict_scroll_to_axis();
    el
}

